/**
 * This test case verifies CBRD-27245: Improve lexer input handling for UTF-8 statements
 *
 * 1-3   - no padding (control): the construct parses correctly nowhere near a boundary
 * 4-18  - padding swept so the critical escape byte lands at the first refill
 *         boundary (absolute offset 8192), at relative offsets -2,-1,0,+1,+2
 * 19-21 - padding swept so the critical escape byte lands exactly on the refill
 *         boundary that follows flex's first buffer-growth event (offset 24583),
 *         proving the split still works once the buffer has grown
 * 22-23 - a large (few hundred KB) multi-row INSERT containing one long value, long
 *         enough to force many buffer refills and at least one buffer-growth event
 *         (every row is checked against its expected pattern afterward)
 * 24    - a semicolon inside a string literal immediately followed by a second
 *         statement on the same line
 * 25-26 - the multi-byte UTF-8 character from cbrd_27245_utf8fix.sql, inside a
 *         literal and as an alias, straddling the first refill boundary (offset
 *         8192) instead of the single-byte ASCII padding used in 4-18
 */

SET SYSTEM PARAMETERS 'no_backslash_escapes=no';

evaluate 'Case 1: pad=0 bytes, escaped quote pair (\') control, no padding';
SELECT 'a\'b', 'END1' FROM db_root;

evaluate 'Case 2: pad=0 bytes, escaped backslash pair (\\) control, no padding';
SELECT 'a\\', 'END2' FROM db_root;

evaluate 'Case 3: pad=0 bytes, backslash-n escape (\\n) control, no padding';
SELECT '\n', 'END3' FROM db_root;

evaluate 'Case 4: pad=8180 bytes, escaped quote pair (\') 2 bytes before the first refill boundary (byte offset 8190, no split)';
SELECT '\'b' AS c1, 'END1' FROM db_root;

evaluate 'Case 5: pad=8181 bytes, escaped quote pair (\') 1 byte before the first refill boundary (byte offset 8191, no split)';
SELECT '\'b' AS c1, 'END1' FROM db_root;

evaluate 'Case 6: pad=8182 bytes, escaped quote pair (\') exactly on the first refill boundary (byte offset 8192), splitting the pair';
SELECT '\'b' AS c1, 'END1' FROM db_root;

evaluate 'Case 7: pad=8183 bytes, escaped quote pair (\') 1 byte after the first refill boundary (byte offset 8193, no split)';
SELECT '\'b' AS c1, 'END1' FROM db_root;

evaluate 'Case 8: pad=8184 bytes, escaped quote pair (\') 2 bytes after the first refill boundary (byte offset 8194, no split)';
SELECT '\'b' AS c1, 'END1' FROM db_root;

evaluate 'Case 9: pad=8180 bytes, escaped backslash pair (\\) 2 bytes before the first refill boundary (byte offset 8190, no split), closing quote right after';
SELECT '\\' AS c1, 'END2' FROM db_root;

evaluate 'Case 10: pad=8181 bytes, escaped backslash pair (\\) 1 byte before the first refill boundary (byte offset 8191, no split), closing quote right after';
SELECT '\\' AS c1, 'END2' FROM db_root;

evaluate 'Case 11: pad=8182 bytes, escaped backslash pair (\\) exactly on the first refill boundary (byte offset 8192), splitting the pair, closing quote right after';
SELECT '\\' AS c1, 'END2' FROM db_root;

evaluate 'Case 12: pad=8183 bytes, escaped backslash pair (\\) 1 byte after the first refill boundary (byte offset 8193, no split), closing quote right after';
SELECT '\\' AS c1, 'END2' FROM db_root;

evaluate 'Case 13: pad=8184 bytes, escaped backslash pair (\\) 2 bytes after the first refill boundary (byte offset 8194, no split), closing quote right after';
SELECT '\\' AS c1, 'END2' FROM db_root;

evaluate 'Case 14: pad=8181 bytes, backslash-n escape (\\n) 2 bytes before the first refill boundary (byte offset 8190, no split)';
SELECT '\n' AS c1, 'END3' FROM db_root;

evaluate 'Case 15: pad=8182 bytes, backslash-n escape (\\n) 1 byte before the first refill boundary (byte offset 8191, no split)';
SELECT '\n' AS c1, 'END3' FROM db_root;

evaluate 'Case 16: pad=8183 bytes, backslash-n escape (\\n) exactly on the first refill boundary (byte offset 8192), splitting the pair';
SELECT '\n' AS c1, 'END3' FROM db_root;

evaluate 'Case 17: pad=8184 bytes, backslash-n escape (\\n) 1 byte after the first refill boundary (byte offset 8193, no split)';
SELECT '\n' AS c1, 'END3' FROM db_root;

evaluate 'Case 18: pad=8185 bytes, backslash-n escape (\\n) 2 bytes after the first refill boundary (byte offset 8194, no split)';
SELECT '\n' AS c1, 'END3' FROM db_root;

evaluate 'Case 19: pad=24573 bytes, escaped quote pair (\') exactly on the refill boundary after the first flex buffer-growth event (byte offset 24583), splitting the pair';
SELECT '\'b' AS c1, 'END1' FROM db_root;

evaluate 'Case 20: pad=24573 bytes, escaped backslash pair (\\) exactly on the refill boundary after the first flex buffer-growth event (byte offset 24583), splitting the pair, closing quote right after';
SELECT '\\' AS c1, 'END2' FROM db_root;

evaluate 'Case 21: pad=24574 bytes, backslash-n escape (\\n) exactly on the refill boundary after the first flex buffer-growth event (byte offset 24583), splitting the pair';
SELECT '\n' AS c1, 'END3' FROM db_root;

DROP TABLE IF EXISTS cbrd_27245_bulk_ins;
CREATE TABLE cbrd_27245_bulk_ins (id INT, val STRING);

evaluate 'Case 22: large multi-row INSERT (~340KB, 4000 rows, one 20000-byte value) forcing many buffer refills and at least one flex buffer-growth event';
